import React from "react"
import styled from "styled-components"
import { Link } from "gatsby"

import { title } from "../../../../blog-config"

const FooterWrapper = styled.footer`
  margin-top: 32px;
  padding: 40px 0;
  border-top: 1px solid ${props => props.theme?.name === 'dark' ? '#2a2a2a' : '#e5e7eb'};
  text-align: center;
  font-size: 11pt;
  font-weight: lighter;
  color: ${props => props.theme?.name === 'dark' ? '#9ca3af' : '#6b7280'};
  
  background: linear-gradient(135deg, 
    ${props => props.theme?.name === 'dark' ? 'rgba(59, 130, 246, 0.03)' : 'rgba(37, 99, 235, 0.02)'} 0%, 
    ${props => props.theme?.name === 'dark' ? 'rgba(139, 92, 246, 0.02)' : 'rgba(147, 51, 234, 0.02)'} 100%
  );

  & a {
    color: ${props => props.theme?.name === 'dark' ? '#9ca3af' : '#6b7280'};
    text-decoration: none;
    transition: color 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    
    &:hover {
      background: linear-gradient(135deg, #2563eb 0%, #7c3aed 100%);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }
  }
`

const FooterLinks = styled.div`
  margin-bottom: 16px;
  font-size: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  
  & > * {
    margin: 0 12px;
    
    @media (max-width: 768px) {
      margin: 4px 6px;
      font-size: 12px;
    }
  }
  
  & span {
    color: ${props => props.theme?.name === 'dark' ? '#4b5563' : '#9ca3af'};
    
    @media (max-width: 480px) {
      display: none;
    }
  }
  
  @media (max-width: 480px) {
    & > a {
      padding: 8px 12px;
      background: ${props => props.theme?.name === 'dark' ? 'rgba(255, 255, 255, 0.05)' : 'rgba(0, 0, 0, 0.05)'};
      border-radius: 8px;
      margin: 4px;
      transition: all 0.3s ease;
      
      &:hover {
        background: linear-gradient(135deg, rgba(37, 99, 235, 0.1) 0%, rgba(147, 51, 234, 0.1) 100%);
      }
    }
  }
`

const Copyright = styled.div`
  margin-top: 16px;
  font-size: 13px;
  
  @media (max-width: 768px) {
    font-size: 11px;
    margin-top: 12px;
  }
`

const Footer = () => {
  const currentYear = new Date().getFullYear()
  
  return (
    <FooterWrapper>
      <FooterLinks>
        <Link to="/about">About</Link>
        <span>·</span>
        <Link to="/privacy">개인정보처리방침</Link>
        <span>·</span>
        <Link to="/terms">이용약관</Link>
        <span>·</span>
        <a href="https://github.com/onseok" target="_blank" rel="noopener noreferrer">GitHub</a>
        <span>·</span>
        <a href="/rss.xml" target="_blank">RSS</a>
      </FooterLinks>
      <Copyright>
        © {currentYear} onseok. Made with code and coffee
      </Copyright>
    </FooterWrapper>
  )
}

export default Footer
