const ToggleWrapper = styled.div`
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  border-radius: 12px;
  background: ${props => props.theme?.name === 'dark' ? '#1a1a1a' : '#ffffff'};
  border: 1px solid ${props => props.theme?.name === 'dark' ? '#2a2a2a' : '#e5e7eb'};
  overflow: hidden;
  cursor: pointer;
  transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  flex-shrink: 0;

  &:hover {
    background: linear-gradient(135deg, #06b6d4 0%, #10b981 100%);
    border-color: #06b6d4;
    transform: translateY(-2px);
    box-shadow: 0 8px 24px rgba(6, 182, 212, 0.4);
  }

  @media (max-width: 768px) {
    width: 40px;
    height: 40px;
    border-radius: 10px;
  }
  
  @media (max-width: 480px) {
    width: 36px;
    height: 36px;
    border-radius: 8px;
  }
`

const IconRail = styled.div`
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  width: 100%;
  height: 100%;
  transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);

  & > svg {
    position: absolute;
    width: 18px;
    height: 18px;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  }

  & > svg path {
    fill: ${props => props.theme?.name === 'dark' ? '#ffffff' : '#6b7280'};
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  }

  ${ToggleWrapper}:hover & > svg path {
    fill: #ffffff;
  }

  & > svg:first-child {
    opacity: ${props => (props.theme === "light" ? 0 : 1)};
    transform: translate(-50%, -50%) ${props => (props.theme === "light" ? "rotate(180deg) scale(0.8)" : "rotate(0deg) scale(1)")};
  }

  & > svg:last-child {
    opacity: ${props => (props.theme === "dark" ? 0 : 1)};
    transform: translate(-50%, -50%) ${props => (props.theme === "dark" ? "rotate(180deg) scale(0.8)" : "rotate(0deg) scale(1)")};
  }

  @media (max-width: 768px) {
    & > svg {
      width: 16px;
      height: 16px;
    }
  }
  
  @media (max-width: 480px) {
    & > svg {
      width: 14px;
      height: 14px;
    }
  }
`

const MenuIconGroup = styled.div`
  display: flex;
  align-items: center;
  gap: 16px;

  @media (max-width: 768px) {
    gap: 12px;
  }
  
  @media (max-width: 480px) {
    gap: 8px;
  }
  
  @media (max-width: 360px) {
    gap: 6px;
  }
`

const Header = React.memo(({ toggleTheme }) => {
  const theme = useTheme()
  const [scrollY, setScrollY] = useState()
  const [hidden, setHidden] = useState(false)

  const detectScrollDirection = useCallback(() => {
    if (scrollY >= window.scrollY) {
      // scroll up
      setHidden(false)
    } else if (scrollY < window.scrollY && 400 <= window.scrollY) {
      // scroll down
      setHidden(true)
    }

    setScrollY(window.scrollY)
  }, [scrollY])

  const handleLogoClick = (e) => {
    e.preventDefault()
    
    // 즉시 스크롤을 맨 위로 이동 (더 빠른 피드백)
    window.scrollTo({ top: 0, behavior: 'smooth' })
    
    // 현재 경로가 홈(/)이 아닌 경우 홈으로 이동
    if (typeof window !== 'undefined' && window.location.pathname !== '/') {
      navigate('/')
    }
  }

  const handleRSSClick = (e) => {
    // 개발 모드에서는 RSS 파일이 없을 수 있으므로 외부 링크로 처리
    if (typeof window !== 'undefined' && window.location.hostname === 'localhost') {
      e.preventDefault()
      window.open('https://onseok.github.io/rss.xml', '_blank')
    }
  }

  useEffect(() => {
    window.addEventListener("scroll", detectScrollDirection)

    return () => {
      window.removeEventListener("scroll", detectScrollDirection)
    }
  }, [scrollY])

  useEffect(() => {
    setScrollY(window.scrollY)
  }, [])

  return (
    <HeaderWrapper isHidden={hidden}>
      <Inner>
        <BlogTitle>
          <Link to="/" onClick={handleLogoClick}>{title}</Link>
        </BlogTitle>
        <Menu>
          <ToggleWrapper onClick={toggleTheme}>
            <IconRail theme={theme.name}>
              <FaSun />
              <FaMoon />
            </IconRail>
          </ToggleWrapper>
          
          <MenuIconGroup>
            <Link to="/rss.xml" onClick={handleRSSClick}>
              <IconWrapper>
                <FaRss />
              </IconWrapper>
            </Link>
            <Link to="/about">
              <IconWrapper>
                <FaUser />
              </IconWrapper>
            </Link>
          </MenuIconGroup>
        </Menu>
      </Inner>
    </HeaderWrapper>
  )
})

export default Header
