import React, { useEffect } from "react"
import { ThemeProvider } from "styled-components"

import { useSelector, useDispatch } from "react-redux"
import { setLight, setDark } from "reducers/theme"

import { light, dark } from "assets/theme"

import GlobalStyles from "components/GlobalStyles"

import Header from "./Header"
import Body from "./Body"
import Footer from "./Footer"

// 기본 fallback 테마
const defaultTheme = {
  name: "light",
  colors: {
    bodyBackground: "#ffffff",
    text: "#0a0a0a",
    secondaryText: "#2a2a2a",
    tertiaryText: "#6b7280",
    mutedText: "#9ca3af",
    hoveredLinkText: "#2563eb",
    border: "#e5e7eb",
    activatedBorder: "#2563eb",
    background: "#f8fafc",
    icon: "#6b7280",
    divider: "#f3f4f6",
    headerBackground: "rgba(255, 255, 255, 0.85)",
    headerShadow: "rgba(37, 99, 235, 0.1)",
    inlineCodeBackground: "#f3f4f6",
    inlineCodeBackgroundDarker: "#d1d5db",
    tagBackground: "#f3f4f6",
    selectedTagBackground: "#2563eb",
    hoveredTagBackground: "#e5e7eb",
    hoveredSelectedTagBackground: "#1d4ed8",
    nextPostButtonBackground: "rgba(37, 99, 235, 0.08)",
    hoveredNextPostButtonBackground: "rgba(37, 99, 235, 0.12)",
    seriesBackground: "#f8fafc",
    tagText: "#2a2a2a",
    selectedTagText: "#ffffff",
    spinner: "#2563eb",
    scrollTrack: "#f3f4f6",
    scrollHandle: "#3b82f6",
    blockQuoteBorder: "#2563eb",
    blockQuoteBackground: "#f8fafc",
    textFieldBorder: "#e5e7eb",
    textFieldActivatedBorder: "#2563eb",
    tableBackground: "#f8fafc",
    primary: "#2563eb",
    primaryLight: "#3b82f6",
    primaryDark: "#1d4ed8",
    secondary: "#7c3aed",
    accent: "#06b6d4",
    success: "#10b981",
    warning: "#f59e0b",
    gradientPrimary: "linear-gradient(135deg, #2563eb 0%, #7c3aed 100%)",
    gradientSecondary: "linear-gradient(135deg, #06b6d4 0%, #10b981 100%)",
    gradientAccent: "linear-gradient(135deg, #f59e0b 0%, #ef4444 100%)",
  },
}

const Layout = ({ children }) => {
  const dispatch = useDispatch()
  const themeState = useSelector(state => state?.theme)
  const theme = themeState?.theme

  let localTheme = null
  if (typeof localStorage !== "undefined") {
    localTheme = localStorage.getItem("theme")
  }

  const toggleTheme = () => {
    const nextTheme = theme === "dark" ? "light" : "dark"
    dispatch(nextTheme === "dark" ? setDark : setLight)
    localStorage.setItem("theme", nextTheme)
    localStorage.setItem("lastThemeToggle", Date.now().toString())
  }

  useEffect(() => {
    // 클라이언트 사이드에서만 실행
    if (typeof window === "undefined") return

    // 시스템 테마 변경 감지를 위한 미디어 쿼리 리스너
    const mediaQuery = window.matchMedia("(prefers-color-scheme: dark)")
    
    const handleSystemThemeChange = (e) => {
      // 사용자가 최근에 수동으로 테마를 변경했는지 확인 (5분 이내)
      const lastUserAction = localStorage.getItem("lastThemeToggle")
      const now = Date.now()
      const fiveMinutes = 5 * 60 * 1000
      
      const recentUserAction = lastUserAction && (now - parseInt(lastUserAction)) < fiveMinutes
      
      if (!recentUserAction) {
        dispatch(e.matches ? setDark : setLight)
      }
    }

    // 초기 테마 설정
    const savedTheme = localStorage.getItem("theme")
    const lastUserAction = localStorage.getItem("lastThemeToggle")
    const now = Date.now()
    const fiveMinutes = 5 * 60 * 1000
    
    const recentUserAction = lastUserAction && (now - parseInt(lastUserAction)) < fiveMinutes
    
    if (savedTheme && recentUserAction) {
      dispatch(savedTheme === "dark" ? setDark : setLight)
    } else {
      dispatch(mediaQuery.matches ? setDark : setLight)
    }

    // 시스템 테마 변경 감지 리스너 등록
    if (mediaQuery.addListener) {
      mediaQuery.addListener(handleSystemThemeChange)
    } else {
      // 최신 브라우저용
      mediaQuery.addEventListener("change", handleSystemThemeChange)
    }

    // 클린업 함수
    return () => {
      if (mediaQuery.removeListener) {
        mediaQuery.removeListener(handleSystemThemeChange)
      } else {
        mediaQuery.removeEventListener("change", handleSystemThemeChange)
      }
    }
  }, [])

  // 모던 스크롤바 효과를 위한 스크롤 이벤트 리스너 (최적화됨)
  useEffect(() => {
    if (typeof window === "undefined") return

    let scrollTimer = null
    let preScrollTimers = new Map()
    let ticking = false

    // 스크롤 이벤트 스로틀링을 위한 requestAnimationFrame 사용
    const handleScroll = () => {
      if (!ticking) {
        requestAnimationFrame(() => {
          document.body.classList.add('scrolling')
          
          if (scrollTimer) {
            clearTimeout(scrollTimer)
          }
          
          scrollTimer = setTimeout(() => {
            document.body.classList.remove('scrolling')
          }, 800) // 0.8초 후 스크롤바 숨김
          
          ticking = false
        })
        ticking = true
      }
    }

    // 스크롤 가능한 요소들의 스크롤 이벤트
    const handleElementScroll = (e) => {
      const element = e.target
      element.classList.add('scrolling')
      
      const existingTimer = preScrollTimers.get(element)
      if (existingTimer) {
        clearTimeout(existingTimer)
      }
      
      const timer = setTimeout(() => {
        element.classList.remove('scrolling')
        preScrollTimers.delete(element)
      }, 1000) // 1초 후 스크롤바 숨김
      
      preScrollTimers.set(element, timer)
    }

    // 이벤트 리스너 등록
    window.addEventListener('scroll', handleScroll, { passive: true })
    
    // 스크롤 가능한 모든 요소에 스크롤 이벤트 리스너 추가
    const addScrollListeners = () => {
      const scrollableSelectors = [
        'pre',
        '.gatsby-highlight',
        'code',
        '.overflow-auto',
        '.overflow-scroll',
        '.overflow-x-auto',
        '.overflow-y-auto',
        '[data-scrollable]'
      ]
      
      scrollableSelectors.forEach(selector => {
        const elements = document.querySelectorAll(selector)
        elements.forEach(element => {
          // 이미 리스너가 등록되었는지 확인
          if (!element.hasAttribute('data-scroll-listener')) {
            element.addEventListener('scroll', handleElementScroll, { passive: true })
            element.setAttribute('data-scroll-listener', 'true')
          }
        })
      })
    }

    // 초기 스크롤 리스너 등록
    addScrollListeners()

    // MutationObserver로 동적으로 추가되는 스크롤 가능한 요소 감지
    const observer = new MutationObserver(() => {
      addScrollListeners()
    })

    observer.observe(document.body, {
      childList: true,
      subtree: true
    })

    // 클린업 함수
    return () => {
      window.removeEventListener('scroll', handleScroll)
      
      if (scrollTimer) {
        clearTimeout(scrollTimer)
      }
      
      preScrollTimers.forEach(timer => clearTimeout(timer))
      preScrollTimers.clear()
      
      observer.disconnect()
      
      // 모든 스크롤 가능한 요소에서 이벤트 리스너 제거
      const scrollableSelectors = [
        'pre',
        '.gatsby-highlight', 
        'code',
        '.overflow-auto',
        '.overflow-scroll',
        '.overflow-x-auto',
        '.overflow-y-auto',
        '[data-scrollable]'
      ]
      
      scrollableSelectors.forEach(selector => {
        const elements = document.querySelectorAll(selector)
        elements.forEach(element => {
          if (element.hasAttribute('data-scroll-listener')) {
            element.removeEventListener('scroll', handleElementScroll)
            element.removeAttribute('data-scroll-listener')
            element.classList.remove('scrolling')
          }
        })
      })
      
      document.body.classList.remove('scrolling')
    }
  }, [])

  // 안전한 테마 선택 - 여러 단계의 fallback
  let currentTheme
  try {
    if (theme === "dark" && dark && dark.colors) {
      currentTheme = dark
    } else if (theme === "light" && light && light.colors) {
      currentTheme = light
    } else if (light && light.colors) {
      currentTheme = light
    } else {
      currentTheme = defaultTheme
    }
  } catch (error) {
    currentTheme = defaultTheme
  }

  return (
    <ThemeProvider theme={currentTheme}>
      <GlobalStyles />
      <Header toggleTheme={toggleTheme} />
      <Body>{children}</Body>
      <Footer />
    </ThemeProvider>
  )
}

export default Layout
